        let secondCalled = false;
        expect(await runBudgetedSemanticCall({ budget, checkpoint: async () => {} }, async () => {
            secondCalled = true;
            return {};
        })).toBeNull();
        expect(secondCalled).toBe(false);
        finish();
        await first;
        expect(budget.spent).toBe(10);
