+export interface DailyViewPoint {
+    date: string;
+    views: number;
+}
+
+export interface DailyViewAnomaly extends DailyViewPoint {
+    baselineViews: number;
+    percentIncrease: number;
+}
+
+const DAY_MS = 24 * 60 * 60 * 1000;
+const BASELINE_DAYS = 7;
+const MIN_BASELINE_SAMPLES = 5;
+const SPIKE_MULTIPLIER = 2.5;
+
+function dateTime(date: string): number | null {
+    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return null;
+    const parsed = Date.parse(`${date}T00:00:00.000Z`);
+    if (!Number.isFinite(parsed) || new Date(parsed).toISOString().slice(0, 10) !== date) return null;
+    return parsed;
+}
+
+/** Accept only finite, nonnegative provider observations with valid calendar dates. */
+export function normalizeDailyViewPoints(rows: readonly DailyViewPoint[]): DailyViewPoint[] {
+    const byDate = new Map<string, DailyViewPoint>();
+    for (const row of rows) {
+        if (!row || dateTime(row.date) === null || !Number.isFinite(row.views) || row.views < 0) continue;
+        byDate.set(row.date, { date: row.date, views: Math.floor(row.views) });
+    }
+    return [...byDate.values()].sort((a, b) => a.date.localeCompare(b.date));
+}
+
+/**
+ * Detect unusual account-level view increases against the previous calendar week.
+ * The result describes a numerical change only; it does not infer a cause.
+ */
+export function detectDailyViewAnomalies(points: readonly DailyViewPoint[]): DailyViewAnomaly[] {
+    const normalized = normalizeDailyViewPoints(points);
+    const anomalies: DailyViewAnomaly[] = [];
+
+    for (const point of normalized) {
+        const currentDate = dateTime(point.date)!;
+        const previousWeek = normalized.filter(candidate => {
+            const candidateDate = dateTime(candidate.date)!;
+            return candidateDate >= currentDate - BASELINE_DAYS * DAY_MS && candidateDate < currentDate;
+        });
+        if (previousWeek.length < MIN_BASELINE_SAMPLES) continue;
+
+        const baselineViews = previousWeek.reduce((total, day) => total + day.views, 0) / previousWeek.length;
+        if (baselineViews <= 0 || point.views <= baselineViews * SPIKE_MULTIPLIER) continue;
+
+        anomalies.push({
+            ...point,
+            baselineViews: Math.round(baselineViews),
+            percentIncrease: Math.round((point.views / baselineViews - 1) * 100),
+        });
+    }
+
+    return anomalies;
+}
